// Generated by OrchestKit Claude Plugin
// Created: 2026-07-31

// Pins the DUAL-SEND contract for search analytics: /api/analytics is the
// system of record and PostHog is a mirror, so every event must reach the
// first-party sink FIRST, independently, and under the SAME name.
//
// The privacy half is pinned here too. Raw query text is allowed on the
// first-party event but must not reach the vendor on the high-volume events:
// truncateQuery is an 80-char length cap, not a redactor, and a docs search box
// is an unbounded input.

import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

const mirrorToPostHog = vi.fn();
vi.mock("@/lib/posthog-mirror", () => ({
	mirrorToPostHog: (name: string, props?: Record<string, unknown>) =>
		mirrorToPostHog(name, props),
}));

import {
	reportSearchPerformed,
	reportSearchResultClicked,
	reportZeroResultQuery,
} from "@/lib/search-beacon";

type Envelope = {
	project_id: string;
	events: {
		name: string;
		path: string;
		properties: Record<string, unknown>;
	}[];
};

let sendBeacon: ReturnType<typeof vi.fn>;
/** Order of sink writes, to prove first-party lands before the mirror. */
let order: string[];

async function firstPartyEvent(callIndex = 0): Promise<Envelope["events"][0]> {
	const blob = sendBeacon.mock.calls[callIndex][1] as Blob;
	return (JSON.parse(await blob.text()) as Envelope).events[0];
}

describe("search beacons", () => {
	beforeEach(() => {
		vi.stubEnv("NODE_ENV", "production");
		order = [];
		mirrorToPostHog.mockReset();
		mirrorToPostHog.mockImplementation(() => order.push("mirror"));
		sendBeacon = vi.fn(() => {
			order.push("first-party");
			return true;
		});
		Object.defineProperty(navigator, "sendBeacon", {
			value: sendBeacon,
			configurable: true,
			writable: true,
		});
		Object.defineProperty(window, "location", {
			value: { ...window.location, pathname: "/docs/skills" },
			configurable: true,
			writable: true,
		});
	});

	afterEach(() => {
		vi.restoreAllMocks();
		vi.unstubAllEnvs();
	});

	it("writes the first-party sink BEFORE the mirror", async () => {
		reportSearchPerformed({ query: "tavily", resultCount: 4, tag: "all" });

		expect(order).toEqual(["first-party", "mirror"]);
		expect(sendBeacon).toHaveBeenCalledWith("/api/analytics", expect.any(Blob));
	});

	it("sends ONE name to both sinks, so they cannot drift", async () => {
		reportSearchPerformed({ query: "tavily", resultCount: 4, tag: "skill" });

		const event = await firstPartyEvent();
		expect(event.name).toBe("search:performed");
		expect(mirrorToPostHog.mock.calls[0][0]).toBe("search:performed");
	});

	it("keeps the raw query first-party only on search:performed", async () => {
		reportSearchPerformed({
			query: "  contact  bob@example.com  ",
			resultCount: 0,
			tag: "all",
		});

		const event = await firstPartyEvent();
		expect(event.properties).toEqual({
			query: "contact  bob@example.com",
			result_count: 0,
			tag: "all",
		});
		// The mirror gets the length, never the text.
		expect(mirrorToPostHog.mock.calls[0][1]).toEqual({
			query_length: 24,
			result_count: 0,
			tag: "all",
		});
	});

	it("carries a ZERO-BASED position on search:result-clicked", async () => {
		reportSearchResultClicked({
			query: "tavily",
			url: "/docs/skills/tavily-search",
			position: 0,
			resultType: "page",
			tag: "all",
		});

		const event = await firstPartyEvent();
		expect(event.name).toBe("search:result-clicked");
		expect(event.properties).toEqual({
			query: "tavily",
			url: "/docs/skills/tavily-search",
			// 0 is a real rank, not a missing value: it must survive the envelope.
			position: 0,
			result_type: "page",
			tag: "all",
		});
		expect(mirrorToPostHog.mock.calls[0][1]).toMatchObject({ position: 0 });
		expect(mirrorToPostHog.mock.calls[0][1]).not.toHaveProperty("query");
	});

	it("stamps the current path on the envelope", async () => {
		reportSearchResultClicked({
			query: "hooks",
			url: "/docs/hooks",
			position: 3,
			resultType: "heading",
			tag: "hook",
		});

		expect((await firstPartyEvent()).path).toBe("/docs/skills");
	});

	it("still mirrors the query on the low-volume zero-result event", async () => {
		reportZeroResultQuery("  qwertyuiop  ");

		const event = await firstPartyEvent();
		expect(event.name).toBe("search:zero-results");
		expect(event.properties).toEqual({ query: "qwertyuiop" });
		expect(mirrorToPostHog).toHaveBeenCalledWith("search:zero-results", {
			query: "qwertyuiop",
		});
	});

	it("drops an empty query instead of logging a blank event", () => {
		reportZeroResultQuery("   ");
		reportSearchPerformed({ query: "  ", resultCount: 0, tag: "all" });

		expect(sendBeacon).not.toHaveBeenCalled();
		expect(mirrorToPostHog).not.toHaveBeenCalled();
	});

	it("truncates the query to 80 chars before it leaves the page", async () => {
		reportSearchPerformed({ query: "x".repeat(200), resultCount: 1, tag: "all" });

		expect((await firstPartyEvent()).properties.query).toHaveLength(80);
	});

	it("does not send from a dev machine", () => {
		vi.stubEnv("NODE_ENV", "development");
		reportSearchPerformed({ query: "tavily", resultCount: 4, tag: "all" });

		expect(sendBeacon).not.toHaveBeenCalled();
		expect(mirrorToPostHog).not.toHaveBeenCalled();
	});

	it("falls back to a keepalive fetch when sendBeacon is missing", async () => {
		Object.defineProperty(navigator, "sendBeacon", {
			value: undefined,
			configurable: true,
			writable: true,
		});
		const fetchMock = vi.fn().mockResolvedValue(undefined);
		vi.stubGlobal("fetch", fetchMock);

		reportSearchResultClicked({
			query: "tavily",
			url: "/docs",
			position: 1,
			resultType: "page",
			tag: "all",
		});

		// keepalive is what survives the navigation a result click starts.
		expect(fetchMock.mock.calls[0][1]).toMatchObject({ keepalive: true });
		vi.unstubAllGlobals();
	});

	it("survives a throwing mirror, because the sink is already written", async () => {
		mirrorToPostHog.mockImplementation(() => {
			throw new Error("posthog blew up");
		});

		expect(() =>
			reportSearchPerformed({ query: "tavily", resultCount: 2, tag: "all" }),
		).not.toThrow();
		expect((await firstPartyEvent()).name).toBe("search:performed");
	});
});
